commands.cmd:
L="$HOME/.local/share/codex-ecosystem/lean"
PIN=$(python3 -c "import json,glob;print(sorted({w['pin'] for f in glob.glob('catalogs/landscape/*.json') for l in json.load(open(f)).get('layers',[]) for w in (l.get('winners') or []) if w.get('component_id')=='lean'})[0])") || { echo "LEAN_SOURCE_FAIL: no winner pin"; exit 1; }
SP=$(python3 -c "import json;print([c['source_pin'] for c in json.load(open('manifests/stack.json'))['components'] if c['id']=='lean'][0])") || { echo "LEAN_SOURCE_FAIL: no stack source_pin"; exit 1; }
HEAD=$(git -C "$L/Lean" --no-optional-locks rev-parse HEAD) || { echo "LEAN_SOURCE_FAIL: no LEAN source tree"; exit 1; }
URL=$(git -C "$L/Lean" --no-optional-locks remote get-url origin) || { echo "LEAN_SOURCE_FAIL: no origin remote"; exit 1; }
git -C "$L/Lean" --no-optional-locks apply --reverse --check "$PWD/blueprints/us-equities/engine/patches/lean-dependencies.patch" || { echo "LEAN_SOURCE_FAIL: tracked changes are not the documented dependency patch"; exit 1; }
DIFF=$(git -C "$L/Lean" --no-optional-locks diff --name-only | sort | tr '\n' ' ')
EXP=$(printf '%s\n' Compression/QuantConnect.Compression.csproj Messaging/QuantConnect.Messaging.csproj Tests/QuantConnect.Tests.csproj | sort | tr '\n' ' ')
SDKS=$(DOTNET_ROOT="$L/dotnet-10.0.401" timeout 20 "$L/dotnet-10.0.401/dotnet" --list-sdks) || { echo "LEAN_SOURCE_FAIL: pinned dotnet SDK did not run"; exit 1; }
if [ -n "$PIN" ] && [ "$PIN" = "$SP" ] && [ "$HEAD" = "$PIN" ] && [ "$DIFF" = "$EXP" ] && printf '%s\n' "$SDKS" | grep -q '^10\.0\.401 ' && [ "$URL" = "https://github.com/QuantConnect/Lean.git" ]; then
  echo "LEAN_SOURCE_OK | source tree HEAD $HEAD == landscape winner pin == manifests/stack.json source_pin | origin $URL | tracked diff == the documented dependency patch | .NET SDK 10.0.401 listed"
else
  echo "LEAN_SOURCE_FAIL | HEAD $HEAD | winner pin $PIN | stack source_pin $SP | origin $URL | diff $DIFF"
  exit 1
fi
echo "patched files: $DIFF| dotnet --list-sdks: $(printf '%s' "$SDKS" | tr '\n' ';')"
